CREATE TABLE IF NOT EXISTS guild_work_offers (
    Id TEXT NOT NULL PRIMARY KEY,
    CohortId TEXT NOT NULL REFERENCES guild_cohorts(Id) ON DELETE RESTRICT,
    IssuerQuestId TEXT NOT NULL REFERENCES guild_quests(Id) ON DELETE RESTRICT,
    OfferSequence INTEGER NOT NULL CHECK(typeof(OfferSequence)='integer' AND OfferSequence>=1),
    SkillId TEXT NOT NULL CHECK(length(CAST(SkillId AS BLOB)) BETWEEN 1 AND 65536),
    GoalContentId TEXT NOT NULL,
    RequestedGrantJson TEXT NOT NULL CHECK(length(CAST(RequestedGrantJson AS BLOB))<=65536),
    BudgetHint INTEGER NOT NULL DEFAULT 0 CHECK(typeof(BudgetHint)='integer' AND BudgetHint IN(0,1)),
    MimeType TEXT NOT NULL CHECK(MimeType IN ('text/plain','application/json')),
    StateCode INTEGER NOT NULL CHECK(StateCode IN (1,2,3,4)),
    Revision INTEGER NOT NULL CHECK(typeof(Revision)='integer' AND Revision>=1),
    BidSequence INTEGER NOT NULL DEFAULT 0 CHECK(typeof(BidSequence)='integer' AND BidSequence>=0),
    AwardId TEXT NULL,
    QuestId TEXT NULL REFERENCES guild_quests(Id) ON DELETE RESTRICT,
    ClosedReason TEXT NULL,
    UNIQUE(CohortId,OfferSequence),
    CHECK((StateCode=2 AND AwardId IS NOT NULL AND QuestId IS NOT NULL) OR (StateCode<>2 AND AwardId IS NULL AND QuestId IS NULL)),
    CHECK(typeof(Id)='text' AND Id=upper(Id) AND length(Id)=36 AND substr(Id,9,1)='-' AND substr(Id,14,1)='-' AND substr(Id,19,1)='-' AND substr(Id,24,1)='-' AND length(replace(Id,'-',''))=32 AND replace(Id,'-','') NOT GLOB '*[^0-9A-F]*' AND Id<>'00000000-0000-0000-0000-000000000000'),
    CHECK(typeof(CohortId)='text' AND CohortId=upper(CohortId) AND length(CohortId)=36 AND substr(CohortId,9,1)='-' AND substr(CohortId,14,1)='-' AND substr(CohortId,19,1)='-' AND substr(CohortId,24,1)='-' AND length(replace(CohortId,'-',''))=32 AND replace(CohortId,'-','') NOT GLOB '*[^0-9A-F]*' AND CohortId<>'00000000-0000-0000-0000-000000000000'),
    CHECK(typeof(IssuerQuestId)='text' AND IssuerQuestId=upper(IssuerQuestId) AND length(IssuerQuestId)=36 AND substr(IssuerQuestId,9,1)='-' AND substr(IssuerQuestId,14,1)='-' AND substr(IssuerQuestId,19,1)='-' AND substr(IssuerQuestId,24,1)='-' AND length(replace(IssuerQuestId,'-',''))=32 AND replace(IssuerQuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND IssuerQuestId<>'00000000-0000-0000-0000-000000000000'),
    CHECK(typeof(GoalContentId)='text' AND GoalContentId=upper(GoalContentId) AND length(GoalContentId)=36 AND substr(GoalContentId,9,1)='-' AND substr(GoalContentId,14,1)='-' AND substr(GoalContentId,19,1)='-' AND substr(GoalContentId,24,1)='-' AND length(replace(GoalContentId,'-',''))=32 AND replace(GoalContentId,'-','') NOT GLOB '*[^0-9A-F]*' AND GoalContentId<>'00000000-0000-0000-0000-000000000000'),
    CHECK(AwardId IS NULL OR (typeof(AwardId)='text' AND AwardId=upper(AwardId) AND length(AwardId)=36 AND substr(AwardId,9,1)='-' AND substr(AwardId,14,1)='-' AND substr(AwardId,19,1)='-' AND substr(AwardId,24,1)='-' AND length(replace(AwardId,'-',''))=32 AND replace(AwardId,'-','') NOT GLOB '*[^0-9A-F]*' AND AwardId<>'00000000-0000-0000-0000-000000000000')),
    CHECK(QuestId IS NULL OR (typeof(QuestId)='text' AND QuestId=upper(QuestId) AND length(QuestId)=36 AND substr(QuestId,9,1)='-' AND substr(QuestId,14,1)='-' AND substr(QuestId,19,1)='-' AND substr(QuestId,24,1)='-' AND length(replace(QuestId,'-',''))=32 AND replace(QuestId,'-','') NOT GLOB '*[^0-9A-F]*' AND QuestId<>'00000000-0000-0000-0000-000000000000'))
);
